		t.Fatalf("line 1 must keep its timestamp-specific reason, got %q", msg)
	}
	if bytes.Contains(w.buf.Bytes(), []byte("tail-in-allowed")) {
		t.Fatalf("the fault's newline-less tail must leave no record: %q", w.buf.String())
	}
}

